const CACHE='my-money-v17';const ASSETS=['./','./index.html','./style.css','./app.js','./manifest.json','./icon.svg','./icon-192.png','./icon-512.png','./icon-maskable-512.png','./apple-touch-icon.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
// Only the app's own files and its fonts are kept for offline use. Sheet replies hold live data and the app token in their URL, so they always go straight to the network.
const cacheable=url=>url.origin===self.location.origin||/^fonts\.(googleapis|gstatic)\.com$/.test(url.hostname);
self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&cacheable(new URL(e.request.url)))e.respondWith(fetch(e.request,e.request.mode==='navigate'?undefined:{cache:'no-cache'}).then(res=>{const copy=res.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));return res}).catch(()=>caches.match(e.request,{ignoreSearch:e.request.mode==='navigate'})))})
